@startuml

class Cinema {
  + Name : string
  + Town : string
}

class Theatre {
  + Number : int
}

class Movie {
  + Title : string
}

class MovieCopy {
  + Id : int
}

class Show {
  + StartTime : datetime
  + EndTime : datetime
  + publish()
  + cancelShow()
}

class Seat {
  + SeatNumber : int
}

class OnlineReservation {
  + ReservationId : int
  + Price : float
  + cancelReservation()
}

class AlternativeOffer {
  + OfferId : int
  + expire()
  + accept()
  + decline()
}

class Ticket {
  + TicketId : int
  + SeatNumber : int
}

class Customer {
  + Name : string
}

Cinema "1" -- "*" Theatre
Cinema "1" -- "*" MovieCopy
Theatre "1" -- "*" Show
Movie "1" -- "*" MovieCopy
MovieCopy "1" -- "*" Show
Show "1" -- "*" OnlineReservation
Show "1" -- "*" Ticket
Show "1" -- "0..1" AlternativeOffer
Theatre "1" -- "*" Seat
Seat "1" -- "0..1" OnlineReservation
Seat "1" -- "0..1" Ticket
Customer "1" -- "*" OnlineReservation
Customer "1" -- "0..1" Ticket

@enduml

